  1266  // <substitution> ::= S_
  1267  //                ::= S <seq-id> _
  1268  //                ::= St, etc.
  1269  static bool ParseSubstitution(State *state) {
  1270    if (ParseTwoCharToken(state, "S_")) {
  1271      MaybeAppend(state, "?");  // We don't support substitutions.
  1272      return true;
  1273    }
  1274
